// ---------------------------------------------------------------------------
// Frozen Single Round and Single Arch — STYLE reference images.
//
// 2026-10-22. "neden referanstakinin exactly same yapamiyorsun?" The round's
// garland is already that photo replayed balloon for balloon in the layout
// guide, but the room, the daylight, the balloons' finish and the flat cut
// lettering are things words kept missing. The photo itself is handed to the
// model as IMAGE 2 (the flux-2 edit models take several image_urls): image 1
// — the guide — still fixes where everything stands; image 2 shows how it all
// looks. Tested on three seeds: room, light, fullness and lettering matched
// the photo, and the plinth held on all three once the opening sentence named
// it. Frozen only — the photo is a Frozen palette, and its blue and lilac would
// bleed into any other.
//
// 2026-10-25: every photo here had its snowflake ornaments removed (one
// flux-2/edit pass each). "Take NOT its snowflakes" in the prompt was not
// enough — a render still copied two of them into the garland. The first
// pass, asked only to remove snowflakes, also took out every chrome and
// clear balloon, and the renders lost them ("silver clear kaybolmus"); the
// photos here are the second pass, told to keep every round balloon.
//
// The customer's reference photo, 720px wide, as a JPEG data URI.
import { hexPaletteKind } from "../balloonSets";
import { BRIGHT_ARCH_STYLE_REFERENCE, UNICORN_ARCH_STYLE_REFERENCE, UNICORN_BRIGHT_ARCH_STYLE_REFERENCE } from "./unicornStyleReferences";

export const ROUND_STYLE_REFERENCE: string =
  "data:image/jpeg;base64,";

// 2026-10-22: the Frozen lone arch likewise, against its reference photo
// ("balonlar referanstakinin aynisi olsun ... gun isigi biraz daha sicaklik
// var ... referanstaki ferahligi yakalayalim"). 640px wide.
export const ARCH_STYLE_REFERENCE: string =
  "data:image/jpeg;base64,";

// 2026-10-22: and the Frozen lone banner, against its reference photo (the
// castle print with the garland over the top right corner). 720px wide.
export const BANNER_STYLE_REFERENCE: string =
  "data:image/jpeg;base64,";

// 2026-10-22: and the Frozen Shimmer Wall and Arch + Shimmer, against theirs
// ("referanstaki netlik yok bizim renderda"): big crisp sequin discs, a lit
// warm-white LED neon "Happy Birthday", two full garland columns. 840px wide.
export const SHIMMER_STYLE_REFERENCE: string =
  "data:image/jpeg;base64,";
export const ARCH_SHIMMER_STYLE_REFERENCE: string =
  "data:image/jpeg;base64,";

// 2026-10-22: and the Frozen Triple Arch, against its reference: without it
// the render read the three boards as one balloon arch ("balonlar backdropu
// sarmis"). 900px wide.
export const TRIPLE_STYLE_REFERENCE: string =
  "data:image/jpeg;base64,";

// 2026-10-22: a close-up of that reference's right-hand garland, for the
// Double Arch — "double backdrop triple gibi isik ayni sicaklikta olsun". A
// close-up, not the whole photo: the whole photo has three boards. 330x640.
export const TRIPLE_GARLAND_CLOSEUP: string =
  "data:image/jpeg;base64,";

/**
 * The style reference a scene is shot against, if any — Frozen, with
 * balloons: a lone round, arch, banner or shimmer wall, an arch beside a
 * shimmer wall, the Double Arch (a close-up only) or the Triple Arch. `board` names the pieces in the prompt, `light` the daylight.
 */
export function sceneStyleReference(scene: { theme?: string; panels: { type: string }[]; balloons?: { style?: string; colors?: string[] } }):
  { image: string; board: string; light: string; closeUp?: boolean } | null {
  // 2026-10-22: every theme, not only Frozen — "frozenda yaptigimiz butun
  // setuplari exactly apply to other all themes except balloon colors". On
  // the other themes the prompt rules out the photo's colours and snowflakes
  // (see frontRoundStyleLine); the balloons take the theme palette from IMAGE 1.
  if ((scene.balloons?.style ?? "none") === "none") return null;
  const types = scene.panels.map((p) => p.type);
  if (types.length === 2 && types.includes("arch") && types.includes("shimmer_wall")) {
    return { image: ARCH_SHIMMER_STYLE_REFERENCE, board: "arch board, the shimmer wall", light: "bright, airy neutral white daylight" };
  }
  if (types.length === 3 && types.filter((t) => t === "half_arch").length === 2 && types.includes("arch")) {
    // (2026-10-22: a garland close-up was tried instead, for a smooth plinth and
    // the customer's sail-shaped side boards; reverted the same day — the
    // balloons floated and the lettering came out heavy. The whole photo stays.)
    return { image: TRIPLE_STYLE_REFERENCE, board: "three boards", light: "bright, airy neutral white daylight" };
  }
  if (types.length === 2 && types.includes("arch") && types.includes("open_arch_frame")) {
    return { image: ARCH_FRAME_STYLE_REFERENCE, board: "arch board and the open arch frame", light: "bright, airy neutral white daylight" };
  }
  if (types.length === 2 && types.every((t) => t === "arch")) {
    return { image: TRIPLE_GARLAND_CLOSEUP, board: "two arch boards", light: "bright, airy neutral white daylight", closeUp: true };
  }
  if (types.length !== 1) return null;
  const t = types[0];
  if (t === "round") return { image: ROUND_STYLE_REFERENCE, board: "round board", light: "bright, airy neutral white daylight" };
  // 2026-11-01: Unicorn's own photo for its lone arch and Wavy (unicornStyleReferences.ts): against the
  // Frozen one its five pastels came back two.
  // 2026-11-02: and the Bright colours set its own bright photo ("pastel tone opsiyon 1 … bright color opsiyon 2"):
  // flux-2/flash/edit takes the balloons' colours from this photo, so a pastel one would turn the bright set pastel.
  const bright = hexPaletteKind(scene.balloons?.colors ?? []) === "bright";
  const archPhoto = scene.theme === "unicorn"
    ? (bright ? UNICORN_BRIGHT_ARCH_STYLE_REFERENCE : UNICORN_ARCH_STYLE_REFERENCE)
    : bright ? BRIGHT_ARCH_STYLE_REFERENCE : ARCH_STYLE_REFERENCE;
  if (t === "arch") return { image: archPhoto, board: "arch board", light: "bright, airy neutral white daylight" };
  // 2026-11-01: the Wavy Backdrop is laid out as a lone arch, so it is shot
  // against the same photo; the guide gives it its wavy outline. The Fringe
  // Backdrop has none — the banner photo's printed board would come back.
  if (t === "wavy") return { image: archPhoto, board: "wavy board", light: "bright, airy neutral white daylight" };
  if (t === "banner") return { image: BANNER_STYLE_REFERENCE, board: "square banner board", light: "bright, airy neutral white daylight" };
  if (t === "shimmer_wall") return { image: SHIMMER_STYLE_REFERENCE, board: "shimmer wall", light: "bright, airy neutral white daylight" };
  return null;
}

// 2026-10-23: the Frozen Arch + Open Frame, against the customer's photo of it
// ("sana ornek attigim gibi duzgun yapalim"): the garland over the arch's crown
// and down its outer side, the frame's over its crown and down its outer side,
// thick with snowflakes, the opening clear. The photo has no lettering, so the
// thin flat lettering of the lone-arch reference is laid onto its solid arch —
// without a reference the render printed it heavy and off the board. 840px wide.
export const ARCH_FRAME_STYLE_REFERENCE: string =
  "data:image/jpeg;base64,";
